using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = AppConfig.Current;
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("Update a configuration value. Returns the old and new values.")]
    public static string SetConfigValue(
        [Description("The configuration key to set")] string key,
        [Description("The new value to assign")] string value)
    {
        var config = AppConfig.Current;
        var had = config.TryGetValue(key, out var old);
        config[key] = value;

        return had
            ? $"Updated '{key}': '{old}' → '{value}'"
            : $"Created '{key}' = '{value}'";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAllSettings() =>
        JsonSerializer.Serialize(AppConfig.Current, AppConfig.JsonOptions);

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "Config Section",
        MimeType = "application/json"),
     Description("Returns configuration entries whose keys start with the given section prefix.")]
    public static string GetSection(string section)
    {
        var filtered = AppConfig.Current
            .Where(kv => kv.Key.StartsWith(section, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

        return filtered.Count > 0
            ? JsonSerializer.Serialize(filtered, AppConfig.JsonOptions)
            : $"No configuration entries found for section '{section}'.";
    }
}

using System.Collections.Concurrent;
using System.Text.Json;

/// <summary>
/// Simple in-memory config store shared by tools and resources.
/// </summary>
public static class AppConfig
{
    public static readonly ConcurrentDictionary<string, string> Current = new(
        new Dictionary<string, string>
        {
            ["App.Name"]        = "ConfigMcpServer",
            ["App.Version"]     = "1.0.0",
            ["App.Environment"] = "Development",
            ["Logging.Level"]   = "Information",
            ["Feature.DarkMode"]= "true",
        });

    public static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true,
    };
}

